def choose_move(observation):
    x, y = observation['self_position']
    w, h = observation['grid_width'], observation['grid_height']
    res_points = observation.get('resources', [])
    opp_x, opp_y = observation.get('opponent_position', (x, y))
    obstacles = set(observation.get('obstacles', []))
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    min_dist = float('inf')
    for r in res_points:
        rp = (r[0], r[1])
        d = dist((x,y), rp)
        if d < min_dist:
            min_dist = d
            target = rp
    def move_towards(src, dst):
        dx = 0 if dst[0] == src[0] else (1 if dst[0] > src[0] else -1)
        dy = 0 if dst[1] == src[1] else (1 if dst[1] > src[1] else -1)
        for nx, ny in [(x+dx,y), (x,y+dy)]:
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
                return [nx - x, ny - y]
        return [0,0]
    if target and dist((x,y), target) > 0:
        dx, dy = move_towards((x,y), target)
        return [dx, dy]
    options = [(-1,0),(1,0),(0,-1),(0,1)]
    best_move = [0,0]
    best_score = -float('inf')
    for dx, dy in options:
        nx, ny = x+dx, y+dy
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
            score = -dist((nx,ny), (opp_x,opp_y))
            if score > best_score:
                best_score = score
                best_move = [dx, dy]
    return best_move
